@extends('admin.layout') @section('title','Campaigns') @section('heading','Campaign Management') @push('styles')<style>.item{margin-bottom:13px}.row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:center}.meta{font-size:12px;color:#667085;margin-top:4px}.status{display:inline-flex;padding:5px 9px;border-radius:99px;background:#eef1ff;color:#4459c5;font-size:11px;font-weight:850}@media(max-width:700px){.row{grid-template-columns:1fr}}</style>@endpush @section('content')@forelse($campaigns as $c)<section class="card item"><div class="row"><div><strong>{{ $c->app_name }}</strong><div class="meta">{{ $c->user->name }} · {{ $c->user->email }}</div><div class="meta">{{ $c->plan }} · {{ $c->duration_days }} days @if($c->ends_at) · Ends {{ $c->ends_at->format('M d, Y') }} @endif</div></div><strong>৳{{ number_format((float)$c->amount,2) }}</strong><div><span class="status">{{ ucfirst($c->status) }}</span><div class="meta">Payment: <strong>{{ ucfirst($c->payment_status ?? "unpaid") }}</strong>@if($c->transaction_id) · {{ $c->transaction_id }}@endif</div></div>@if(!in_array($c->status,['completed','cancelled']))<form method="POST" action="{{ route('admin.campaigns.update',$c) }}">@csrf @method('PATCH')<select class="input" name="status">@if($c->status==='pending')<option value="pending">Pending</option><option value="active" @disabled(($c->payment_status ?? 'unpaid')!=='paid')>Activate</option><option value="cancelled">Cancel</option>@elseif($c->status==='active')<option value="active">Active</option><option value="completed">Complete</option><option value="cancelled">Cancel</option>@endif</select><button class="btn" style="margin-top:6px;width:100%">Update</button></form>@else<span class="status">Finalized</span>@endif</div></section>@empty<section class="card"><p class="muted">No campaigns yet.</p></section>@endforelse{{ $campaigns->links() }}@endsection